// Module 8 translations (es, de, ja). Code, identifiers and test logic stay untouched; only display text.
(function () {
const T = window.QMLCAMP.tr;
const add = (l, o) => { T[l] = Object.assign(T[l] || {}, o); };
// shared wording of the five workshop steps: <p><b>Step n of 5.</b> what</p><p>previous-code note</p>extra
const step = (head, note) => (n, what, extra) => '<p><b>' + head(n) + '</b> ' + what + '</p><p>' + note + '</p>' + (extra || '');

// ================================================================= Español
{
const S = step(n => 'Paso ' + n + ' de 5.', 'El código de la derecha es tu trabajo terminado del paso anterior. Busca los comentarios <code>// TODO</code> (indican qué escribir) y haz que pasen las pruebas.');
add('es', {
 'm8-t1': { title: 'Planifica la isla', desc: 'Modos, una única fuente de verdad, transformación, clics que atraviesan.',
  lessons: [
   { title: 'Modos y una única fuente de verdad', html: '<p>Una Dynamic Island es una pequeña forma con varios <b>modos</b>: <i>idle</i> (reloj), <i>osd</i> (volumen), <i>notify</i> (un mensaje), <i>expanded</i> (una lista). El truco para mantener el código sencillo: <b>un</b> solo sitio guarda el estado y lo visual solo lo <i>lee</i>.</p><ul><li><b>Store</b> (un <code>Singleton</code>): <code>mode</code>, <code>volume</code>, el modelo de notificaciones y funciones como <code>showVolume(v)</code>. Los temporizadores que vuelven a idle viven aquí también.</li><li><b>Island</b> (un componente): solo el aspecto. Los tamaños y la visibilidad son enlaces a <code>Store.mode</code>.</li><li><b>main.qml</b>: ventanas e <code>IpcHandler</code>s. El IPC solo llama a funciones del Store; nunca toca lo visual.</li></ul><p>La documentación real de Quickshell está en <code>quickshell.org/docs</code>; el mismo patrón mueve tu dynisland.</p>',
     q: { text: '¿Por qué los temporizadores que vuelven a <code>idle</code> viven en el <code>Store</code> y no en el componente visual?', options: ['Los componentes visuales no pueden contener un Timer', 'El comportamiento pertenece al estado; así la isla de cada pantalla muestra el mismo modo', 'Los Timer solo funcionan dentro de singletons', 'Hace el código más corto en todos los casos'], why: 'El estado y sus reglas viven en un solo sitio; cada isla es una vista de él.' } },
   { title: 'Transformación: states más Behavior', html: '<p>Cada modo es un <code>State</code> con <code>when: Store.mode === "osd"</code> y un <code>PropertyChanges</code> que fija <code>width</code> y <code>height</code>. Un <code>Behavior on width</code> y un <code>Behavior on height</code> animan cada cambio, así que la forma se transforma. Haz que el <code>radius</code> lo siga con <code>Math.min(height / 2, 20)</code>: una píldora cuando es pequeña, un rectángulo redondeado cuando es grande.</p><p>Solo debe verse lo visual del modo <b>actual</b>: da a cada bloque de contenido <code>visible: Store.mode === "..."</code>.</p>',
     q: { text: '¿Qué hace que la píldora se <b>anime</b> hacia su nuevo tamaño cuando cambia el estado?', options: ['El propio <code>State</code>', '<code>Behavior on width</code> / <code>Behavior on height</code>', 'El enlace de <code>radius</code>', 'La condición <code>when</code>'], why: 'Un State cambia los valores; un Behavior anima cualquier cambio de una propiedad.' } },
   { title: 'Ventanas: clic a través, capa, espacio', html: '<p>La isla flota sobre otras ventanas, así que el <code>PanelWindow</code> es más grande que la píldora (espacio para crecer) pero no debe bloquear los clics a su alrededor:</p><ul><li><code>exclusiveZone: 0</code>: no reserva <b>nada</b> de espacio de pantalla (las ventanas se disponen por debajo).</li><li><code>color: "transparent"</code>: solo se dibuja la píldora.</li><li><code>mask: Region { item: island }</code>: solo el área de la píldora recibe entrada; el resto de la ventana deja pasar los clics.</li><li><code>WlrLayershell.layer: WlrLayer.Overlay</code> y un <code>namespace</code>: se dibuja sobre todo y se le pone nombre para las reglas del compositor.</li><li><code>Variants</code> sobre <code>Quickshell.screens</code>: una isla por pantalla, todas leyendo el mismo Store.</li></ul>',
     q: { text: '¿Qué hace <code>mask: Region { item: island }</code>?', options: ['Oculta la isla', 'Solo el área de la isla recibe entrada del ratón; los clics en otras zonas de la ventana pasan a través', 'Redondea las esquinas de la ventana', 'Hace que la ventana reserve espacio'], why: 'La máscara es la región de entrada de la ventana.' } }
  ] },
 'm8-l1': { title: 'Paso 1: Shell y píldora en reposo', desc: 'Ventana, reloj del Store, la píldora en reposo.',
  desc2: S(1, 'Crea la ventana, un singleton <code>Store</code> con el reloj y la píldora en reposo que muestra la hora.', '<p>Archivos: <code>main.qml</code> (la ventana), <code>Store.qml</code> (singleton), <code>Island.qml</code> (la píldora: 120 x 28, redonda, negra, centrada arriba, <code>y: 8</code>, un <code>Text</code> blanco con la hora).</p>'),
  stories: ['<code>Store.qml</code> es un singleton y <code>Store.time</code> es <code>"12:00"</code>, y luego <code>"12:01"</code> tras 61 segundos.', 'Un <code>PanelWindow</code> <code>win</code> anclado arriba, a la izquierda y a la derecha (no abajo), de 150 de alto y tan ancho como la pantalla.', 'La ventana no reserva espacio (<code>exclusiveZone: 0</code>) y es <b>transparente</b>.', 'La píldora (<code>island</code>) mide 120 x 28, es negra, tiene los extremos redondos (radio 14), está centrada en horizontal y a 8 px del borde superior.', 'Un <code>Text</code> blanco en el centro de la píldora muestra <code>Store.time</code> y lo sigue.'] },
 'm8-l2': { title: 'Paso 2: Modos y transformación', desc: 'States, Behavior, un clic para expandir.',
  desc2: S(2, 'Añade el <code>mode</code> al Store y haz que la píldora se transforme entre idle, osd, notify y expanded. Un clic en la píldora alterna expanded.', '<table class="cs"><tr><th>modo</th><th>tamaño</th></tr><tr><td>idle</td><td>120 x 28</td></tr><tr><td>osd</td><td>220 x 44</td></tr><tr><td>notify</td><td>300 x 56</td></tr><tr><td>expanded</td><td>320 x 130</td></tr></table>'),
  stories: ['<code>Store.mode</code> empieza en <code>"idle"</code> y la píldora mide 120 x 28.', 'Cada modo tiene su tamaño: osd 220 x 44, notify 300 x 56, expanded 320 x 130; al volver a idle vuelve a medir 120 x 28.', 'La píldora usa <b>states</b> (3 o más <code>State</code>) y se anima con <code>Behavior on width</code> y <code>Behavior on height</code> (100 a 400 ms).', 'Las esquinas siguen el tamaño: <code>radius</code> es la mitad de la altura, pero nunca más de 20.', 'La etiqueta de la hora solo se muestra en modo idle.', 'Al hacer clic en la píldora se expande; otro clic la contrae. <code>Store.toggleExpanded()</code> hace el cambio.'] },
 'm8-l3': { title: 'Paso 3: OSD de volumen por IPC', desc: 'IpcHandler, Timer, una barra de progreso.',
  desc2: S(3, 'Un OSD de volumen: <code>qs ipc call osd volume 70</code> muestra el OSD durante 1,5 segundos. Llamarlo de nuevo <b>reinicia</b> el temporizador.', '<p>Mientras la isla está <b>expanded</b>, un cambio de volumen actualiza <code>Store.volume</code> pero no sale del modo expanded.</p>'),
  stories: ['Un <code>IpcHandler</code> con target <code>"osd"</code> tiene <code>volume(v)</code>. <code>volume(70)</code> pone <code>Store.volume</code> a 70 y el modo a <code>"osd"</code>; la píldora pasa a 220 x 44.', 'Los valores se limitan al rango 0..100.', 'El OSD muestra <code>Volume 70</code> y una barra verde (<code>#4cd964</code>) que ocupa el 70 % de la pista de 80 px (56 px). Ambos están ocultos fuera del modo osd.', 'Tras 1,5 segundos sin una nueva llamada, la isla vuelve a <b>idle</b>.', 'Una segunda llamada <b>reinicia</b> el temporizador: con llamadas a los 0 s y 1 s, el OSD sigue ahí a los 2 s y desaparece a los 2,6 s.', 'En modo expanded, <code>volume()</code> actualiza el valor pero mantiene la isla expandida.'] },
 'm8-l4': { title: 'Paso 4: Notificaciones', desc: 'ListModel en el Store, modo notify, lista expandida.',
  desc2: S(4, 'Notificaciones: <code>qs ipc call notify push Mail "Hello"</code> muestra la más reciente durante 3 segundos. La isla expandida las lista y cada fila se puede descartar. Termina el Store, los tres bloques visuales y el segundo manejador IPC.'),
  stories: ['<code>notify push</code> añade una fila (la más reciente primero), el modo pasa a <code>"notify"</code> y la píldora mide 300 x 56 mostrando la app y el texto.', 'Tras 3 segundos la isla vuelve a idle y muestra la insignia <code>● 1</code>.', 'El modelo mantiene lo <b>más reciente primero</b> y como máximo <b>4</b> notificaciones.', 'El modo expanded lista cada notificación como <code>app: text</code> (oculta en los demás modos).', 'Una notificación nueva estando en expanded se añade a la lista pero no sale del modo expanded.', 'El área de descartar de una fila elimina <b>esa</b> fila (los índices siguen siendo correctos tras la primera eliminación). Quitar la última fila cierra la isla expandida.', '<code>notify clear</code> elimina todas las notificaciones y sale del modo expanded.'] },
 'm8-l5': { title: 'Paso 5: Todas las pantallas, clic a través, overlay', desc: 'Variants, máscara, layer shell.',
  desc2: S(5, 'Termina el shell: una isla en <b>cada pantalla</b> (todas mostrando el mismo Store), clic a través fuera de la píldora y la ventana en la capa overlay.', '<p>Reescribe <code>main.qml</code>: envuelve la ventana en un <code>Variants</code> sobre <code>Quickshell.screens</code> (<code>required property var modelData</code>, <code>screen: modelData</code>), añade <code>mask: Region { item: island }</code>, <code>WlrLayershell.layer: WlrLayer.Overlay</code>, <code>WlrLayershell.namespace: "island"</code> e <code>import Quickshell.Wayland</code>. Conserva los dos <code>IpcHandler</code>. <code>Island.qml</code> y <code>Store.qml</code> se quedan como están.</p>'),
  stories: ['Un <code>Variants</code> sobre <code>Quickshell.screens</code> crea una ventana <b>y</b> una <code>Island</code> por pantalla (2 pantallas en el sandbox).', 'Cada ventana está anclada arriba, a la izquierda y a la derecha, mide 150 de alto, no reserva espacio y es transparente.', 'Cada ventana está en la capa <b>Overlay</b> con el namespace <code>"island"</code>.', 'La <code>mask</code> de entrada de cada ventana es una <code>Region</code> alrededor de su propia isla y <b>sigue</b> a la isla cuando crece.', 'Todas las islas comparten el Store: una llamada IPC cambia todas las pantallas y cada píldora está centrada.', 'Los manejadores IPC siguen funcionando: <code>notify push</code> muestra la notificación en todas las pantallas.'] },
 'm8-q': { title: 'Test de práctica: diseño de la isla', desc: 'Ocho preguntas antes del examen final.', questions: [
  { text: '¿Por qué el <code>PanelWindow</code> es más alto que la píldora en reposo?', options: ['Una ventana debe medir al menos 150 px', 'Debe haber espacio para que la isla crezca sin redimensionar la ventana', 'exclusiveZone lo exige', 'Las ventanas transparentes necesitan altura extra'], why: 'Redimensionar una ventana de layer shell es costoso y parpadea; redimensiona la píldora dentro de ella.' },
  { text: 'La isla no debe empujar otras ventanas hacia abajo. ¿Qué ajuste es el responsable?', options: ['<code>exclusiveZone: 0</code>', '<code>exclusiveZone: 150</code>', '<code>color: "transparent"</code>', '<code>mask</code>'], why: 'exclusiveZone es el espacio que reserva la ventana.' },
  { text: '¿Para qué sirve <code>mask: Region { item: island }</code>?', options: ['Hace invisible la isla', 'Limita la entrada a la isla; el resto de la ventana deja pasar los clics', 'Recorta el dibujo a la isla', 'Anima la isla'], why: 'Define la región de entrada.' },
  { text: 'Un único singleton <code>Store</code> se comparte entre todas las pantallas. ¿Qué ventaja tiene?', options: ['Renderizado más rápido', 'La isla de cada pantalla muestra el mismo modo y los mismos datos sin código extra', 'Evita Variants', 'Elimina la necesidad de IPC'], why: 'Una única fuente de verdad.' },
  { text: 'Llamas a <code>osdTimer.restart()</code> en cada llamada de volumen. ¿Por qué?', options: ['Para ocultar el OSD de inmediato', 'Para que los cambios repetidos mantengan el OSD abierto 1,5 s después del <b>último</b>', 'Para reiniciar el volumen', 'Los temporizadores hay que reiniciarlos para que funcionen'], why: 'restart() reinicia la cuenta atrás.' },
  { text: 'Un <code>State</code> fija <code>width: 220</code>. ¿Qué anima el cambio?', options: ['<code>Behavior on width</code>', '<code>PropertyChanges</code>', 'La expresión <code>when</code>', 'Nada, no se puede animar'], why: 'Un Behavior anima cada cambio de esa propiedad.' },
  { text: 'Dentro del delegado de notificaciones quieres el nombre de la app. ¿Qué es lo más seguro?', options: ['<code>model.app</code>', '<code>app</code>', '<code>parent.app</code>', '<code>ListView.app</code>'], why: '<code>model.role</code> no puede quedar oculto por propiedades del elemento.' },
  { text: '¿Qué llamada desde un shell atiende la isla con un <code>IpcHandler</code>?', options: ['<code>qs ipc call osd volume 70</code>', '<code>qs run osd</code>', '<code>qs osd.volume = 70</code>', '<code>qs kill osd</code>'], why: '<code>qs ipc call TARGET FUNCTION ARGS</code>.' }
 ] },
 'm8-x': { title: 'Examen final: isla de batería', desc: 'Certificación: construye una isla nueva solo a partir de la especificación.',
  desc2: '<p><b>Examen final.</b> Sin TODOs y sin pistas en el código. Construye una <b>isla de batería</b> a partir de esta especificación. Cada punto de la lista es una prueba; apruebas cuando todas están en verde.</p>\n<h3>Archivos</h3><p><code>main.qml</code> (shell), <code>Power.qml</code> (singleton), <code>Pill.qml</code> (la píldora).</p>\n<h3>Power.qml</h3><ul><li><code>property int battery</code> (80), <code>property bool charging</code> (false), <code>property bool open</code> (false).</li><li><code>readonly property string mode</code>: <code>"expanded"</code> cuando <code>open</code>; si no, <code>"alert"</code> cuando <code>battery &lt;= 20</code> y no está cargando; si no, <code>"idle"</code>.</li><li><code>readonly property var devices</code>: un <code>ListModel</code> con los roles <code>name</code> y <code>level</code>: Laptop 80, Mouse 55, Keyboard 12.</li><li><code>function setBattery(p)</code>: limita a 0..100.</li></ul>\n<h3>main.qml</h3><ul><li><code>Variants</code> sobre <code>Quickshell.screens</code>: un <code>PanelWindow</code> por pantalla, anclado arriba, a la izquierda y a la derecha; <code>implicitHeight: 140</code>; <code>exclusiveZone: 0</code>; transparente.</li><li>Capa overlay, namespace <code>"power"</code>; <code>mask: Region { item: pill }</code> donde <code>Pill { id: pill }</code> está dentro de la ventana.</li><li><code>IpcHandler</code> con target <code>"power"</code>: <code>level(p: int)</code> llama a <code>Power.setBattery(p)</code>; <code>plug(value: bool)</code> fija <code>Power.charging</code>; <code>toggle()</code> invierte <code>Power.open</code>.</li></ul>\n<h3>Pill.qml</h3><ul><li>Rectangle, centrado arriba, <code>y: 6</code>, negro. Tamaños: idle 100 x 26, alert 240 x 48, expanded 300 x 120, elegidos con <b>states</b> sobre <code>Power.mode</code>, animados con <code>Behavior</code> en width y height (150 a 400 ms). <code>radius: Math.min(height / 2, 18)</code>.</li><li>Idle: texto blanco <code>Power.battery + "%"</code> (p. ej. <code>80%</code>). Alert: texto <code>Low battery: 15%</code>. Cada uno solo en su modo.</li><li>Expanded: un <code>ListView</code> sobre <code>Power.devices</code> con filas como <code>Mouse: 55%</code>; las filas con nivel 20 o menos son <code>#ff5555</code>, las demás blancas. Solo en modo expanded.</li><li>Un <code>MouseArea</code> a lo largo del borde superior (alto 26) alterna <code>Power.open</code>.</li></ul>',
  stories: ['<b>Singleton:</b> <code>Power.qml</code> empieza con <code>pragma Singleton</code> y su raíz es <code>Singleton</code>; valores por defecto: battery 80, charging false, open false, mode <code>"idle"</code>.', '<b>Ventanas:</b> un <code>PanelWindow</code> por pantalla desde <code>Variants</code>, anclado arriba, a la izquierda y a la derecha (no abajo), de 140 de alto, <code>exclusiveZone: 0</code>, transparente.', '<b>Capa:</b> cada ventana está en la capa Overlay con el namespace <code>"power"</code>.', '<b>Máscara:</b> cada ventana tiene <code>mask: Region { item: pill }</code>, donde la píldora es su propia <code>Pill</code>, de 100 x 26 en reposo, centrada, <code>y: 6</code>.', '<b>Reposo:</b> el texto <code>80%</code> se muestra en todas las pantallas; no se ve ningún texto de alerta.', '<b>IPC:</b> <code>power level</code> fija la batería (limitada a 0..100) y el texto de reposo la sigue.', '<b>Alerta:</b> al 15 % el modo es <code>"alert"</code>, la píldora mide 240 x 48 con radio 18 y el texto <code>Low battery: 15%</code> sustituye al de reposo.', '<b>Límite:</b> el 20 % es una alerta, el 21 % no.', '<b>Cargar</b> cancela la alerta; desenchufar la devuelve.', '<b>Expandida:</b> <code>power toggle</code> abre una píldora de 300 x 120 (tiene prioridad sobre alert) con las filas <code>Laptop: 80%</code>, <code>Mouse: 55%</code>, <code>Keyboard: 12%</code>; alternar otra vez la cierra.', '<b>Colores:</b> las filas con nivel 20 o menos son <code>#ff5555</code> (Keyboard), las demás blancas.', '<b>Clic:</b> al hacer clic en la píldora se expande, otro clic la contrae.', '<b>Movimiento:</b> la píldora usa <code>State</code>s y <code>Behavior</code> en width y height (150 a 400 ms).'] },
 'm8-r': { title: 'Repaso: proyecto de la isla', desc: 'La arquitectura, una lista de comprobación y qué hacer a continuación.',
  html: '<h2>Has construido una Dynamic Island</h2>\n<table class="cs"><tr><th>Pieza</th><th>Regla</th></tr>\n<tr><td><code>Store</code> (Singleton)</td><td>Todo el estado y sus reglas: modo, datos, modelos, temporizadores. Las funciones son la única forma de cambiarlo.</td></tr>\n<tr><td><code>Island</code> (componente)</td><td>Solo el aspecto. <code>states</code> + <code>when</code> eligen el tamaño, <code>Behavior</code> anima, <code>visible</code> elige el contenido.</td></tr>\n<tr><td><code>main.qml</code></td><td><code>Variants</code> sobre las pantallas, ajustes de <code>PanelWindow</code>, <code>IpcHandler</code>s que llaman a funciones del Store.</td></tr>\n<tr><td>Ventana</td><td>Más alta que la píldora; <code>exclusiveZone: 0</code>; transparente; <code>mask</code> sobre la píldora; capa Overlay; un namespace.</td></tr>\n<tr><td>Listas</td><td><code>ListModel</code> en el Store, <code>ListView</code> + delegado en la isla, <code>model.role</code> e <code>index</code>.</td></tr>\n<tr><td>Temporizadores</td><td><code>restart()</code> en cada disparo para que solo cuente el último evento.</td></tr></table>\n<h3>Lista de certificación</h3>\n<ul><li>Sé explicar por qué el estado vive en un singleton.</li><li>Sé construir modos con states y animarlos con Behavior.</li><li>Sé hacer que una ventana deje pasar los clics con una máscara y evitar que reserve espacio.</li><li>Sé añadir funciones IPC y llamarlas desde una terminal.</li><li>Sé mostrar un modelo con un ListView y eliminar filas por índice.</li></ul>\n<p><b>Siguiente:</b> prueba las ideas en tu shell real. Ideas: un modo multimedia (título de la pista con <code>Process</code>), una lista de la bandeja desde <code>Quickshell.Services.SystemTray</code>, espacios de trabajo desde un <code>Process</code> que imprime eventos de niri con un <code>SplitParser</code>. El sandbox no ejecuta esto, pero la documentación real de Quickshell en <code>quickshell.org/docs</code> sí lo cubre.</p>' }
});
}

// ================================================================= Deutsch
{
const S = step(n => 'Schritt ' + n + ' von 5.', 'Der Code rechts ist deine fertige Arbeit aus dem vorherigen Schritt. Suche die <code>// TODO</code>-Kommentare (sie nennen, was zu schreiben ist) und lass die Tests bestehen.');
add('de', {
 'm8-t1': { title: 'Die Island planen', desc: 'Modi, eine einzige Quelle der Wahrheit, Morphing, Klick-durch.',
  lessons: [
   { title: 'Modi und eine einzige Quelle der Wahrheit', html: '<p>Eine Dynamic Island ist eine kleine Form mit mehreren <b>Modi</b>: <i>idle</i> (Uhr), <i>osd</i> (Lautstärke), <i>notify</i> (eine Nachricht), <i>expanded</i> (eine Liste). Der Trick, der den Code einfach hält: <b>eine</b> Stelle speichert den Zustand, und die Darstellung <i>liest</i> ihn nur.</p><ul><li><b>Store</b> (ein <code>Singleton</code>): <code>mode</code>, <code>volume</code>, das Benachrichtigungsmodell und Funktionen wie <code>showVolume(v)</code>. Auch die Timer, die zu idle zurückkehren, leben hier.</li><li><b>Island</b> (eine Komponente): nur das Aussehen. Größen und Sichtbarkeit sind Bindings auf <code>Store.mode</code>.</li><li><b>main.qml</b>: Fenster und <code>IpcHandler</code>. IPC ruft nur Store-Funktionen auf und berührt nie die Darstellung.</li></ul><p>Die echte Quickshell-Dokumentation findest du unter <code>quickshell.org/docs</code>; dasselbe Muster treibt deine dynisland an.</p>',
     q: { text: 'Warum leben die Timer, die zu <code>idle</code> zurückkehren, im <code>Store</code> und nicht in der visuellen Komponente?', options: ['Visuelle Komponenten können keinen Timer enthalten', 'Verhalten gehört zum Zustand; dann zeigt die Island jedes Bildschirms denselben Modus', 'Timer laufen nur in Singletons', 'Es macht den Code in jedem Fall kürzer'], why: 'Der Zustand und seine Regeln liegen an einer Stelle; jede Island ist eine Ansicht darauf.' } },
   { title: 'Morphing: States plus Behavior', html: '<p>Jeder Modus ist ein <code>State</code> mit <code>when: Store.mode === "osd"</code> und einem <code>PropertyChanges</code>, das <code>width</code> und <code>height</code> setzt. Ein <code>Behavior on width</code> und ein <code>Behavior on height</code> animieren jede Änderung, sodass die Form morpht. Lass den <code>radius</code> mit <code>Math.min(height / 2, 20)</code> folgen: eine Pille, wenn sie klein ist, ein abgerundetes Rechteck, wenn sie groß ist.</p><p>Nur die Darstellung des <b>aktuellen</b> Modus soll sichtbar sein: gib jedem Inhaltsblock <code>visible: Store.mode === "..."</code>.</p>',
     q: { text: 'Was sorgt dafür, dass die Pille beim Zustandswechsel zur neuen Größe <b>animiert</b>?', options: ['Der <code>State</code> selbst', '<code>Behavior on width</code> / <code>Behavior on height</code>', 'Das <code>radius</code>-Binding', 'Die <code>when</code>-Bedingung'], why: 'Ein State ändert die Werte; ein Behavior animiert jede Änderung einer Eigenschaft.' } },
   { title: 'Fenster: Klick-durch, Ebene, Platz', html: '<p>Die Island schwebt über anderen Fenstern, daher ist das <code>PanelWindow</code> größer als die Pille (Platz zum Wachsen), darf aber Klicks rundherum nicht blockieren:</p><ul><li><code>exclusiveZone: 0</code>: reserviert <b>keinen</b> Bildschirmplatz (Fenster kacheln darunter).</li><li><code>color: "transparent"</code>: nur die Pille wird gezeichnet.</li><li><code>mask: Region { item: island }</code>: nur der Bereich der Pille empfängt Eingaben; der Rest des Fensters lässt Klicks durch.</li><li><code>WlrLayershell.layer: WlrLayer.Overlay</code> und ein <code>namespace</code>: über allem zeichnen, für Compositor-Regeln benennen.</li><li><code>Variants</code> über <code>Quickshell.screens</code>: eine Island pro Bildschirm, alle lesen denselben Store.</li></ul>',
     q: { text: 'Was bewirkt <code>mask: Region { item: island }</code>?', options: ['Blendet die Island aus', 'Nur der Bereich der Island empfängt Mauseingaben; Klicks an anderen Stellen des Fensters gehen durch', 'Rundet die Ecken des Fensters ab', 'Lässt das Fenster Platz reservieren'], why: 'Die Maske ist die Eingaberegion des Fensters.' } }
  ] },
 'm8-l1': { title: 'Schritt 1: Shell und Ruhe-Pille', desc: 'Fenster, Store-Uhr, die Pille im Ruhezustand.',
  desc2: S(1, 'Erstelle das Fenster, ein <code>Store</code>-Singleton mit der Uhr und die Ruhe-Pille, die die Uhrzeit zeigt.', '<p>Dateien: <code>main.qml</code> (das Fenster), <code>Store.qml</code> (Singleton), <code>Island.qml</code> (die Pille: 120 x 28, rund, schwarz, oben zentriert, <code>y: 8</code>, ein weißer <code>Text</code> mit der Uhrzeit).</p>'),
  stories: ['<code>Store.qml</code> ist ein Singleton und <code>Store.time</code> ist <code>"12:00"</code>, nach 61 Sekunden dann <code>"12:01"</code>.', 'Ein <code>PanelWindow</code> <code>win</code>, oben, links und rechts verankert (nicht unten), 150 hoch, so breit wie der Bildschirm.', 'Das Fenster reserviert keinen Platz (<code>exclusiveZone: 0</code>) und ist <b>transparent</b>.', 'Die Pille (<code>island</code>) ist 120 x 28, schwarz, hat runde Enden (Radius 14), ist horizontal zentriert und sitzt 8 px vom oberen Rand.', 'Ein weißer <code>Text</code> in der Mitte der Pille zeigt <code>Store.time</code> und folgt ihm.'] },
 'm8-l2': { title: 'Schritt 2: Modi und Morphing', desc: 'States, Behavior, ein Klick zum Aufklappen.',
  desc2: S(2, 'Füge dem Store den <code>mode</code> hinzu und lass die Pille zwischen idle, osd, notify und expanded morphen. Ein Klick auf die Pille schaltet expanded um.', '<table class="cs"><tr><th>Modus</th><th>Größe</th></tr><tr><td>idle</td><td>120 x 28</td></tr><tr><td>osd</td><td>220 x 44</td></tr><tr><td>notify</td><td>300 x 56</td></tr><tr><td>expanded</td><td>320 x 130</td></tr></table>'),
  stories: ['<code>Store.mode</code> beginnt als <code>"idle"</code> und die Pille ist 120 x 28.', 'Jeder Modus hat seine Größe: osd 220 x 44, notify 300 x 56, expanded 320 x 130; zurück zu idle ergibt wieder 120 x 28.', 'Die Pille ist mit <b>States</b> gebaut (3 oder mehr <code>State</code>) und mit <code>Behavior on width</code> und <code>Behavior on height</code> animiert (100 bis 400 ms).', 'Die Ecken folgen der Größe: <code>radius</code> ist die halbe Höhe, aber nie mehr als 20.', 'Das Zeit-Label wird nur im Modus idle angezeigt.', 'Ein Klick auf die Pille klappt sie auf; ein weiterer Klick klappt sie zu. <code>Store.toggleExpanded()</code> übernimmt das Umschalten.'] },
 'm8-l3': { title: 'Schritt 3: Lautstärke-OSD per IPC', desc: 'IpcHandler, Timer, ein Fortschrittsbalken.',
  desc2: S(3, 'Ein Lautstärke-OSD: <code>qs ipc call osd volume 70</code> zeigt das OSD 1,5 Sekunden lang. Ein erneuter Aufruf <b>startet den Timer neu</b>.', '<p>Solange die Island <b>expanded</b> ist, aktualisiert eine Lautstärkeänderung <code>Store.volume</code>, verlässt aber den Modus expanded nicht.</p>'),
  stories: ['Ein <code>IpcHandler</code> mit target <code>"osd"</code> hat <code>volume(v)</code>. <code>volume(70)</code> setzt <code>Store.volume</code> auf 70 und den Modus auf <code>"osd"</code>; die Pille wird 220 x 44.', 'Die Werte werden auf 0..100 begrenzt.', 'Das OSD zeigt <code>Volume 70</code> und einen grünen Balken (<code>#4cd964</code>), der 70 % der 80 px breiten Spur (56 px) ausfüllt. Beides ist außerhalb des osd-Modus verborgen.', 'Nach 1,5 Sekunden ohne neuen Aufruf geht die Island zurück zu <b>idle</b>.', 'Ein zweiter Aufruf <b>startet den Timer neu</b>: bei Aufrufen nach 0 s und 1 s ist das OSD nach 2 s noch da und nach 2,6 s weg.', 'Im Modus expanded aktualisiert <code>volume()</code> den Wert, lässt die Island aber aufgeklappt.'] },
 'm8-l4': { title: 'Schritt 4: Benachrichtigungen', desc: 'ListModel im Store, notify-Modus, aufgeklappte Liste.',
  desc2: S(4, 'Benachrichtigungen: <code>qs ipc call notify push Mail "Hello"</code> zeigt die neueste 3 Sekunden lang. Die aufgeklappte Island listet sie auf, und jede Zeile lässt sich verwerfen. Vervollständige den Store, die drei visuellen Blöcke und den zweiten IPC-Handler.'),
  stories: ['<code>notify push</code> fügt eine Zeile hinzu (neueste zuerst), der Modus wird <code>"notify"</code> und die Pille ist 300 x 56 und zeigt App und Text.', 'Nach 3 Sekunden kehrt die Island zu idle zurück und zeigt das Abzeichen <code>● 1</code>.', 'Das Modell hält die <b>neueste zuerst</b> und höchstens <b>4</b> Benachrichtigungen.', 'Der Modus expanded listet jede Benachrichtigung als <code>app: text</code> (in anderen Modi verborgen).', 'Eine neue Benachrichtigung im Modus expanded wird zur Liste hinzugefügt, verlässt aber den Modus expanded nicht.', 'Der Verwerfen-Bereich einer Zeile entfernt <b>genau diese</b> Zeile (die Indizes stimmen auch nach der ersten Entfernung). Das Entfernen der letzten Zeile schließt die aufgeklappte Island.', '<code>notify clear</code> entfernt alle Benachrichtigungen und verlässt den Modus expanded.'] },
 'm8-l5': { title: 'Schritt 5: Jeder Bildschirm, Klick-durch, Overlay', desc: 'Variants, Maske, Layer Shell.',
  desc2: S(5, 'Vervollständige die Shell: eine Island auf <b>jedem Bildschirm</b> (alle zeigen denselben Store), Klick-durch außerhalb der Pille und das Fenster auf der Overlay-Ebene.', '<p>Schreibe <code>main.qml</code> um: Umhülle das Fenster mit einem <code>Variants</code> über <code>Quickshell.screens</code> (<code>required property var modelData</code>, <code>screen: modelData</code>), füge <code>mask: Region { item: island }</code>, <code>WlrLayershell.layer: WlrLayer.Overlay</code>, <code>WlrLayershell.namespace: "island"</code> und <code>import Quickshell.Wayland</code> hinzu. Behalte beide <code>IpcHandler</code>. <code>Island.qml</code> und <code>Store.qml</code> bleiben unverändert.</p>'),
  stories: ['Ein <code>Variants</code> über <code>Quickshell.screens</code> erzeugt pro Bildschirm ein Fenster <b>und</b> eine <code>Island</code> (2 Bildschirme in der Sandbox).', 'Jedes Fenster ist oben, links und rechts verankert, 150 hoch, reserviert keinen Platz und ist transparent.', 'Jedes Fenster liegt auf der <b>Overlay</b>-Ebene mit dem Namespace <code>"island"</code>.', 'Die Eingabe-<code>mask</code> jedes Fensters ist eine <code>Region</code> um die eigene Island und <b>folgt</b> der Island, wenn sie wächst.', 'Alle Islands teilen sich den Store: Ein IPC-Aufruf ändert jeden Bildschirm, und jede Pille ist zentriert.', 'Die IPC-Handler funktionieren weiterhin: <code>notify push</code> zeigt die Benachrichtigung auf jedem Bildschirm.'] },
 'm8-q': { title: 'Übungstest: Island-Design', desc: 'Acht Fragen vor der Abschlussprüfung.', questions: [
  { text: 'Warum ist das <code>PanelWindow</code> höher als die Ruhe-Pille?', options: ['Ein Fenster muss mindestens 150 px hoch sein', 'Es muss Platz sein, damit die Island wachsen kann, ohne das Fenster zu ändern', 'exclusiveZone verlangt es', 'Transparente Fenster brauchen zusätzliche Höhe'], why: 'Die Größe eines Layer-Shell-Fensters zu ändern ist teuer und flackert; ändere stattdessen die Pille darin.' },
  { text: 'Die Island darf andere Fenster nicht nach unten schieben. Welche Einstellung ist dafür zuständig?', options: ['<code>exclusiveZone: 0</code>', '<code>exclusiveZone: 150</code>', '<code>color: "transparent"</code>', '<code>mask</code>'], why: 'exclusiveZone ist der Platz, den das Fenster reserviert.' },
  { text: 'Was ist die Aufgabe von <code>mask: Region { item: island }</code>?', options: ['Macht die Island unsichtbar', 'Beschränkt Eingaben auf die Island; der Rest des Fensters lässt Klicks durch', 'Beschneidet das Zeichnen auf die Island', 'Animiert die Island'], why: 'Sie legt die Eingaberegion fest.' },
  { text: 'Ein einziges <code>Store</code>-Singleton wird von allen Bildschirmen geteilt. Was ist der Vorteil?', options: ['Schnelleres Rendern', 'Die Island jedes Bildschirms zeigt denselben Modus und dieselben Daten ohne zusätzlichen Code', 'Es erspart Variants', 'Es macht IPC überflüssig'], why: 'Eine einzige Quelle der Wahrheit.' },
  { text: 'Du rufst bei jedem Lautstärke-Aufruf <code>osdTimer.restart()</code> auf. Warum?', options: ['Um das OSD sofort auszublenden', 'Damit wiederholte Änderungen das OSD 1,5 s nach der <b>letzten</b> offen halten', 'Um die Lautstärke zurückzusetzen', 'Timer müssen neu gestartet werden, um zu laufen'], why: 'restart() setzt den Countdown zurück.' },
  { text: 'Ein <code>State</code> setzt <code>width: 220</code>. Was animiert die Änderung?', options: ['<code>Behavior on width</code>', '<code>PropertyChanges</code>', 'Der <code>when</code>-Ausdruck', 'Nichts, das lässt sich nicht animieren'], why: 'Ein Behavior animiert jede Änderung dieser Eigenschaft.' },
  { text: 'Im Benachrichtigungs-Delegate willst du den App-Namen. Was ist am sichersten?', options: ['<code>model.app</code>', '<code>app</code>', '<code>parent.app</code>', '<code>ListView.app</code>'], why: '<code>model.role</code> kann nicht von Eigenschaften des Items verdeckt werden.' },
  { text: 'Welchen Aufruf aus einer Shell behandelt die Island mit einem <code>IpcHandler</code>?', options: ['<code>qs ipc call osd volume 70</code>', '<code>qs run osd</code>', '<code>qs osd.volume = 70</code>', '<code>qs kill osd</code>'], why: '<code>qs ipc call TARGET FUNCTION ARGS</code>.' }
 ] },
 'm8-x': { title: 'Abschlussprüfung: Akku-Island', desc: 'Zertifizierung: Baue eine neue Island nur anhand der Spezifikation.',
  desc2: '<p><b>Abschlussprüfung.</b> Keine TODOs, keine Hinweise im Code. Baue eine <b>Akku-Island</b> nach dieser Spezifikation. Jeder Punkt der Checkliste ist ein Test; du bestehst, wenn alle grün sind.</p>\n<h3>Dateien</h3><p><code>main.qml</code> (Shell), <code>Power.qml</code> (Singleton), <code>Pill.qml</code> (die Pille).</p>\n<h3>Power.qml</h3><ul><li><code>property int battery</code> (80), <code>property bool charging</code> (false), <code>property bool open</code> (false).</li><li><code>readonly property string mode</code>: <code>"expanded"</code>, wenn <code>open</code>; sonst <code>"alert"</code>, wenn <code>battery &lt;= 20</code> und nicht geladen wird; sonst <code>"idle"</code>.</li><li><code>readonly property var devices</code>: ein <code>ListModel</code> mit den Rollen <code>name</code> und <code>level</code>: Laptop 80, Mouse 55, Keyboard 12.</li><li><code>function setBattery(p)</code>: auf 0..100 begrenzen.</li></ul>\n<h3>main.qml</h3><ul><li><code>Variants</code> über <code>Quickshell.screens</code>: ein <code>PanelWindow</code> pro Bildschirm, oben, links, rechts verankert; <code>implicitHeight: 140</code>; <code>exclusiveZone: 0</code>; transparent.</li><li>Overlay-Ebene, Namespace <code>"power"</code>; <code>mask: Region { item: pill }</code>, wobei <code>Pill { id: pill }</code> im Fenster liegt.</li><li><code>IpcHandler</code> mit target <code>"power"</code>: <code>level(p: int)</code> ruft <code>Power.setBattery(p)</code> auf; <code>plug(value: bool)</code> setzt <code>Power.charging</code>; <code>toggle()</code> kehrt <code>Power.open</code> um.</li></ul>\n<h3>Pill.qml</h3><ul><li>Rectangle, oben zentriert, <code>y: 6</code>, schwarz. Größen: idle 100 x 26, alert 240 x 48, expanded 300 x 120, per <b>States</b> auf <code>Power.mode</code> gewählt, mit <code>Behavior</code> auf width und height animiert (150 bis 400 ms). <code>radius: Math.min(height / 2, 18)</code>.</li><li>Idle: weißer Text <code>Power.battery + "%"</code> (z. B. <code>80%</code>). Alert: Text <code>Low battery: 15%</code>. Jeweils nur im eigenen Modus.</li><li>Expanded: ein <code>ListView</code> über <code>Power.devices</code> mit Zeilen wie <code>Mouse: 55%</code>; Zeilen mit Level 20 oder weniger sind <code>#ff5555</code>, die anderen weiß. Nur im Modus expanded.</li><li>Eine <code>MouseArea</code> am oberen Rand (Höhe 26) schaltet <code>Power.open</code> um.</li></ul>',
  stories: ['<b>Singleton:</b> <code>Power.qml</code> beginnt mit <code>pragma Singleton</code> und seine Wurzel ist <code>Singleton</code>; Standardwerte: battery 80, charging false, open false, mode <code>"idle"</code>.', '<b>Fenster:</b> ein <code>PanelWindow</code> pro Bildschirm aus <code>Variants</code>, oben, links, rechts verankert (nicht unten), 140 hoch, <code>exclusiveZone: 0</code>, transparent.', '<b>Ebene:</b> Jedes Fenster liegt auf der Overlay-Ebene mit dem Namespace <code>"power"</code>.', '<b>Maske:</b> Jedes Fenster hat <code>mask: Region { item: pill }</code>, wobei die Pille seine eigene <code>Pill</code> ist, im Ruhezustand 100 x 26, zentriert, <code>y: 6</code>.', '<b>Ruhe:</b> Der Text <code>80%</code> erscheint auf jedem Bildschirm; kein Alarmtext ist sichtbar.', '<b>IPC:</b> <code>power level</code> setzt den Akku (auf 0..100 begrenzt), und der Ruhetext folgt.', '<b>Alarm:</b> Bei 15 % ist der Modus <code>"alert"</code>, die Pille ist 240 x 48 mit Radius 18, und der Text <code>Low battery: 15%</code> ersetzt den Ruhetext.', '<b>Grenzfall:</b> 20 % ist ein Alarm, 21 % nicht.', '<b>Laden</b> hebt den Alarm auf; Abstecken bringt ihn zurück.', '<b>Aufgeklappt:</b> <code>power toggle</code> öffnet eine 300 x 120 große Pille (sie hat Vorrang vor alert) mit den Zeilen <code>Laptop: 80%</code>, <code>Mouse: 55%</code>, <code>Keyboard: 12%</code>; erneutes Umschalten schließt sie.', '<b>Farben:</b> Zeilen mit Level 20 oder weniger sind <code>#ff5555</code> (Keyboard), die anderen weiß.', '<b>Klick:</b> Ein Klick auf die Pille klappt sie auf, ein weiterer klappt sie zu.', '<b>Bewegung:</b> Die Pille nutzt <code>State</code>s und <code>Behavior</code> auf width und height (150 bis 400 ms).'] },
 'm8-r': { title: 'Wiederholung: Island-Projekt', desc: 'Die Architektur, eine Checkliste und wie es weitergeht.',
  html: '<h2>Du hast eine Dynamic Island gebaut</h2>\n<table class="cs"><tr><th>Baustein</th><th>Regel</th></tr>\n<tr><td><code>Store</code> (Singleton)</td><td>Gesamter Zustand und seine Regeln: Modus, Daten, Modelle, Timer. Funktionen sind der einzige Weg, ihn zu ändern.</td></tr>\n<tr><td><code>Island</code> (Komponente)</td><td>Nur das Aussehen. <code>states</code> + <code>when</code> wählen die Größe, <code>Behavior</code> animiert, <code>visible</code> wählt den Inhalt.</td></tr>\n<tr><td><code>main.qml</code></td><td><code>Variants</code> über die Bildschirme, <code>PanelWindow</code>-Einstellungen, <code>IpcHandler</code>, die Store-Funktionen aufrufen.</td></tr>\n<tr><td>Fenster</td><td>Höher als die Pille; <code>exclusiveZone: 0</code>; transparent; <code>mask</code> auf der Pille; Overlay-Ebene; ein Namespace.</td></tr>\n<tr><td>Listen</td><td><code>ListModel</code> im Store, <code>ListView</code> + Delegate in der Island, <code>model.role</code> und <code>index</code>.</td></tr>\n<tr><td>Timer</td><td><code>restart()</code> bei jedem Auslöser, damit nur das letzte Ereignis zählt.</td></tr></table>\n<h3>Zertifizierungs-Checkliste</h3>\n<ul><li>Ich kann erklären, warum der Zustand in einem Singleton liegt.</li><li>Ich kann Modi mit States bauen und mit Behavior animieren.</li><li>Ich kann ein Fenster mit einer Maske klick-durchlässig machen und verhindern, dass es Platz reserviert.</li><li>Ich kann IPC-Funktionen hinzufügen und aus einem Terminal aufrufen.</li><li>Ich kann ein Modell mit einem ListView anzeigen und Zeilen per Index entfernen.</li></ul>\n<p><b>Als Nächstes:</b> Probiere die Ideen in deiner echten Shell aus. Ideen: ein Medien-Modus (Titel per <code>Process</code>), eine Tray-Liste aus <code>Quickshell.Services.SystemTray</code>, Arbeitsbereiche aus einem <code>Process</code>, der niri-Ereignisse mit einem <code>SplitParser</code> ausgibt. Die Sandbox führt das nicht aus, die echte Quickshell-Dokumentation unter <code>quickshell.org/docs</code> deckt es ab.</p>' }
});
}

// ================================================================= 日本語
{
const S = step(n => 'ステップ ' + n + '/5。', '右側のコードは、前のステップであなたが完成させたものです。<code>// TODO</code> コメント(書くべき内容が書いてあります)を探して、テストに合格させましょう。');
add('ja', {
 'm8-t1': { title: 'アイランドを設計する', desc: 'モード、唯一の信頼できる情報源、モーフィング、クリックの透過。',
  lessons: [
   { title: 'モードと唯一の信頼できる情報源', html: '<p>Dynamic Island は、いくつかの<b>モード</b>を持つ小さな形です:<i>idle</i>(時計)、<i>osd</i>(音量)、<i>notify</i>(メッセージ)、<i>expanded</i>(リスト)。コードをシンプルに保つコツは、状態を保存する場所を<b>1 か所</b>にして、見た目はそれを<i>読むだけ</i>にすることです。</p><ul><li><b>Store</b>(<code>Singleton</code>):<code>mode</code>、<code>volume</code>、通知のモデル、<code>showVolume(v)</code> のような関数。idle に戻すタイマーもここに置きます。</li><li><b>Island</b>(コンポーネント):見た目だけ。サイズと表示/非表示は <code>Store.mode</code> へのバインディングです。</li><li><b>main.qml</b>:ウィンドウと <code>IpcHandler</code>。IPC は Store の関数を呼ぶだけで、見た目には触れません。</li></ul><p>本物の Quickshell のドキュメントは <code>quickshell.org/docs</code> にあります。同じパターンがあなたの dynisland を動かしています。</p>',
     q: { text: 'なぜ <code>idle</code> に戻すタイマーは、見た目のコンポーネントではなく <code>Store</code> に置くのですか?', options: ['見た目のコンポーネントには Timer を置けないから', '振る舞いは状態に属するから。そうすれば各画面のアイランドが同じモードを表示する', 'Timer は Singleton の中でしか動かないから', 'どんな場合でもコードが短くなるから'], why: '状態とそのルールは 1 か所にあり、各アイランドはそのビューです。' } },
   { title: 'モーフィング:State と Behavior', html: '<p>各モードは、<code>when: Store.mode === "osd"</code> を持つ <code>State</code> と、<code>width</code> と <code>height</code> を設定する <code>PropertyChanges</code> です。<code>Behavior on width</code> と <code>Behavior on height</code> がすべての変化をアニメーションさせるので、形がモーフィングします。<code>radius</code> は <code>Math.min(height / 2, 20)</code> で追従させます:小さいときはピル型、大きいときは角丸の長方形です。</p><p><b>現在の</b>モードの見た目だけを表示します。各コンテンツブロックに <code>visible: Store.mode === "..."</code> を付けましょう。</p>',
     q: { text: '状態が変わったとき、ピルが新しいサイズへ<b>アニメーション</b>するのは何のおかげですか?', options: ['<code>State</code> そのもの', '<code>Behavior on width</code> / <code>Behavior on height</code>', '<code>radius</code> のバインディング', '<code>when</code> の条件'], why: 'State は値を変え、Behavior はプロパティのあらゆる変化をアニメーションさせます。' } },
   { title: 'ウィンドウ:クリック透過、レイヤー、スペース', html: '<p>アイランドは他のウィンドウの上に浮かぶので、<code>PanelWindow</code> はピルより大きく(成長する余地)しますが、周囲のクリックを妨げてはいけません:</p><ul><li><code>exclusiveZone: 0</code>:画面のスペースを<b>確保しない</b>(ウィンドウは下にタイル表示される)。</li><li><code>color: "transparent"</code>:ピルだけが描画される。</li><li><code>mask: Region { item: island }</code>:ピルの領域だけが入力を受け取り、ウィンドウの残りはクリックが通り抜ける。</li><li><code>WlrLayershell.layer: WlrLayer.Overlay</code> と <code>namespace</code>:すべての上に描画し、コンポジタのルール用に名前を付ける。</li><li><code>Quickshell.screens</code> に対する <code>Variants</code>:画面ごとに 1 つのアイランド、すべて同じ Store を読む。</li></ul>',
     q: { text: '<code>mask: Region { item: island }</code> は何をしますか?', options: ['アイランドを隠す', 'アイランドの領域だけがマウス入力を受け取り、ウィンドウ内の他の場所のクリックは通り抜ける', 'ウィンドウの角を丸める', 'ウィンドウにスペースを確保させる'], why: 'マスクはウィンドウの入力領域です。' } }
  ] },
 'm8-l1': { title: 'ステップ 1:シェルとアイドルのピル', desc: 'ウィンドウ、Store の時計、アイドル状態のピル。',
  desc2: S(1, 'ウィンドウと、時計を持つ <code>Store</code> の Singleton、そして時刻を表示するアイドルのピルを作ります。', '<p>ファイル:<code>main.qml</code>(ウィンドウ)、<code>Store.qml</code>(Singleton)、<code>Island.qml</code>(ピル:120 x 28、丸い、黒、上部中央、<code>y: 8</code>、時刻を表示する白い <code>Text</code>)。</p>'),
  stories: ['<code>Store.qml</code> は Singleton で、<code>Store.time</code> は <code>"12:00"</code>、61 秒後は <code>"12:01"</code> になる。', '<code>PanelWindow</code> の <code>win</code> が上・左・右にアンカーされ(下はなし)、高さ 150、画面と同じ幅である。', 'ウィンドウは場所を確保せず(<code>exclusiveZone: 0</code>)、<b>透明</b>である。', 'ピル(<code>island</code>)は 120 x 28 で黒く、端が丸く(半径 14)、水平方向の中央にあり、上端から 8 px の位置にある。', 'ピルの中央にある白い <code>Text</code> が <code>Store.time</code> を表示し、その変化に追従する。'] },
 'm8-l2': { title: 'ステップ 2:モードとモーフィング', desc: 'State、Behavior、クリックで展開。',
  desc2: S(2, 'Store に <code>mode</code> を追加し、ピルが idle、osd、notify、expanded の間でモーフィングするようにします。ピルをクリックすると expanded が切り替わります。', '<table class="cs"><tr><th>モード</th><th>サイズ</th></tr><tr><td>idle</td><td>120 x 28</td></tr><tr><td>osd</td><td>220 x 44</td></tr><tr><td>notify</td><td>300 x 56</td></tr><tr><td>expanded</td><td>320 x 130</td></tr></table>'),
  stories: ['<code>Store.mode</code> は <code>"idle"</code> で始まり、ピルは 120 x 28 である。', '各モードにサイズがある:osd 220 x 44、notify 300 x 56、expanded 320 x 130。idle に戻ると再び 120 x 28 になる。', 'ピルは<b>状態</b>(<code>State</code> が 3 つ以上)で作られ、<code>Behavior on width</code> と <code>Behavior on height</code>(100〜400 ms)でアニメーションする。', '角はサイズに追従する:<code>radius</code> は高さの半分だが、20 を超えない。', '時刻のラベルは idle モードのときだけ表示される。', 'ピルをクリックすると展開し、もう一度クリックすると折りたたまれる。切り替えは <code>Store.toggleExpanded()</code> が行う。'] },
 'm8-l3': { title: 'ステップ 3:IPC による音量 OSD', desc: 'IpcHandler、Timer、プログレスバー。',
  desc2: S(3, '音量 OSD:<code>qs ipc call osd volume 70</code> で OSD が 1.5 秒間表示されます。もう一度呼ぶとタイマーが<b>再スタート</b>します。', '<p>アイランドが <b>expanded</b> の間は、音量を変えても <code>Store.volume</code> は更新されますが、expanded モードからは出ません。</p>'),
  stories: ['target が <code>"osd"</code> の <code>IpcHandler</code> に <code>volume(v)</code> がある。<code>volume(70)</code> は <code>Store.volume</code> を 70 に、モードを <code>"osd"</code> にし、ピルは 220 x 44 になる。', '値は 0..100 に制限される。', 'OSD は <code>Volume 70</code> と、80 px のトラックの 70 %(56 px)の緑のバー(<code>#4cd964</code>)を表示する。どちらも osd モード以外では非表示である。', '新しい呼び出しなしで 1.5 秒たつと、アイランドは <b>idle</b> に戻る。', '2 回目の呼び出しでタイマーが<b>再スタート</b>する:0 秒と 1 秒に呼ぶと、OSD は 2 秒時点でまだ表示され、2.6 秒で消える。', 'expanded の間、<code>volume()</code> は値を更新するが、アイランドは展開したままである。'] },
 'm8-l4': { title: 'ステップ 4:通知', desc: 'Store の ListModel、notify モード、展開リスト。',
  desc2: S(4, '通知:<code>qs ipc call notify push Mail "Hello"</code> で最新の通知が 3 秒間表示されます。展開したアイランドは通知を一覧表示し、各行を消去できます。Store、3 つの見た目のブロック、2 つ目の IPC ハンドラーを完成させましょう。'),
  stories: ['<code>notify push</code> は行を追加し(新しい順)、モードは <code>"notify"</code> になり、ピルは 300 x 56 でアプリ名とテキストを表示する。', '3 秒後にアイランドは idle に戻り、バッジ <code>● 1</code> を表示する。', 'モデルは<b>新しい順</b>に保ち、通知は最大 <b>4</b> 件までである。', 'expanded モードは各通知を <code>app: text</code> として一覧表示する(他のモードでは非表示)。', 'expanded 中の新しい通知はリストに追加されるが、expanded モードからは出ない。', '行の消去エリアは<b>その</b>行を削除する(最初の削除後もインデックスが正しい)。最後の行を削除すると、展開したアイランドが閉じる。', '<code>notify clear</code> はすべての通知を削除し、expanded モードから出る。'] },
 'm8-l5': { title: 'ステップ 5:全画面、クリック透過、オーバーレイ', desc: 'Variants、マスク、layer shell。',
  desc2: S(5, 'シェルを仕上げます:<b>すべての画面</b>に 1 つずつアイランド(すべて同じ Store を表示)、ピルの外はクリック透過、ウィンドウはオーバーレイレイヤーに置きます。', '<p><code>main.qml</code> を書き直します:ウィンドウを <code>Quickshell.screens</code> に対する <code>Variants</code> で包み(<code>required property var modelData</code>、<code>screen: modelData</code>)、<code>mask: Region { item: island }</code>、<code>WlrLayershell.layer: WlrLayer.Overlay</code>、<code>WlrLayershell.namespace: "island"</code> を追加し、<code>import Quickshell.Wayland</code> を加えます。2 つの <code>IpcHandler</code> はそのまま残します。<code>Island.qml</code> と <code>Store.qml</code> は変更しません。</p>'),
  stories: ['<code>Quickshell.screens</code> に対する <code>Variants</code> が、画面ごとにウィンドウ<b>と</b> <code>Island</code> を 1 つずつ作る(サンドボックスでは 2 画面)。', '各ウィンドウは上・左・右にアンカーされ、高さ 150 で、場所を確保せず、透明である。', '各ウィンドウは <b>Overlay</b> レイヤーにあり、namespace は <code>"island"</code> である。', '各ウィンドウの入力 <code>mask</code> は自分のアイランドを囲む <code>Region</code> で、アイランドが大きくなるとそれに<b>追従</b>する。', 'すべてのアイランドが Store を共有する:IPC 呼び出しですべての画面が変わり、どのピルも中央にある。', 'IPC ハンドラーは引き続き動く:<code>notify push</code> はすべての画面に通知を表示する。'] },
 'm8-q': { title: '練習テスト:アイランドの設計', desc: '最終試験の前の 8 問。', questions: [
  { text: 'なぜ <code>PanelWindow</code> はアイドルのピルより高いのですか?', options: ['ウィンドウは最低 150 px 必要だから', 'ウィンドウのサイズを変えずにアイランドが成長できる余地が必要だから', 'exclusiveZone が要求するから', '透明なウィンドウには余分な高さが必要だから'], why: 'layer shell のウィンドウのリサイズは高コストでちらつきます。ウィンドウ内のピルをリサイズしましょう。' },
  { text: 'アイランドは他のウィンドウを下に押し下げてはいけません。どの設定が担当しますか?', options: ['<code>exclusiveZone: 0</code>', '<code>exclusiveZone: 150</code>', '<code>color: "transparent"</code>', '<code>mask</code>'], why: 'exclusiveZone はウィンドウが確保するスペースです。' },
  { text: '<code>mask: Region { item: island }</code> の役割は何ですか?', options: ['アイランドを見えなくする', '入力をアイランドに限定し、ウィンドウの残りはクリックが通り抜ける', '描画をアイランドの範囲に切り抜く', 'アイランドをアニメーションさせる'], why: '入力領域を定義します。' },
  { text: '1 つの <code>Store</code> Singleton がすべての画面で共有されます。利点は何ですか?', options: ['描画が速くなる', '余分なコードなしで、各画面のアイランドが同じモードとデータを表示する', 'Variants が不要になる', 'IPC が不要になる'], why: '唯一の信頼できる情報源です。' },
  { text: '音量が呼ばれるたびに <code>osdTimer.restart()</code> を呼びます。なぜですか?', options: ['OSD をすぐに隠すため', '繰り返し変更しても、<b>最後</b>の変更から 1.5 秒間 OSD を開いたままにするため', '音量をリセットするため', 'タイマーは再スタートしないと動かないため'], why: 'restart() はカウントダウンをリセットします。' },
  { text: '<code>State</code> が <code>width: 220</code> を設定します。その変化をアニメーションさせるのは何ですか?', options: ['<code>Behavior on width</code>', '<code>PropertyChanges</code>', '<code>when</code> 式', '何もない、アニメーションさせられない'], why: 'Behavior はそのプロパティのあらゆる変化をアニメーションさせます。' },
  { text: '通知のデリゲート内でアプリ名が欲しいとき、最も安全なのはどれですか?', options: ['<code>model.app</code>', '<code>app</code>', '<code>parent.app</code>', '<code>ListView.app</code>'], why: '<code>model.role</code> はアイテムのプロパティに隠されることがありません。' },
  { text: 'シェルからのどの呼び出しを、アイランドは <code>IpcHandler</code> で処理しますか?', options: ['<code>qs ipc call osd volume 70</code>', '<code>qs run osd</code>', '<code>qs osd.volume = 70</code>', '<code>qs kill osd</code>'], why: '<code>qs ipc call TARGET FUNCTION ARGS</code>。' }
 ] },
 'm8-x': { title: '最終試験:バッテリーアイランド', desc: '認定:仕様だけを見て新しいアイランドを作る。',
  desc2: '<p><b>最終試験。</b>TODO もコード内のヒントもありません。この仕様から<b>バッテリーアイランド</b>を作ってください。チェックリストの各項目が 1 つのテストで、すべて緑になれば合格です。</p>\n<h3>ファイル</h3><p><code>main.qml</code>(シェル)、<code>Power.qml</code>(Singleton)、<code>Pill.qml</code>(ピル)。</p>\n<h3>Power.qml</h3><ul><li><code>property int battery</code>(80)、<code>property bool charging</code>(false)、<code>property bool open</code>(false)。</li><li><code>readonly property string mode</code>:<code>open</code> のとき <code>"expanded"</code>、そうでなく <code>battery &lt;= 20</code> かつ充電中でなければ <code>"alert"</code>、それ以外は <code>"idle"</code>。</li><li><code>readonly property var devices</code>:ロール <code>name</code> と <code>level</code> を持つ <code>ListModel</code>:Laptop 80、Mouse 55、Keyboard 12。</li><li><code>function setBattery(p)</code>:0..100 に制限する。</li></ul>\n<h3>main.qml</h3><ul><li><code>Quickshell.screens</code> に対する <code>Variants</code>:画面ごとに 1 つの <code>PanelWindow</code>、上・左・右にアンカー、<code>implicitHeight: 140</code>、<code>exclusiveZone: 0</code>、透明。</li><li>Overlay レイヤー、namespace <code>"power"</code>、<code>mask: Region { item: pill }</code>(<code>Pill { id: pill }</code> はウィンドウの中に置く)。</li><li>target <code>"power"</code> の <code>IpcHandler</code>:<code>level(p: int)</code> は <code>Power.setBattery(p)</code> を呼び、<code>plug(value: bool)</code> は <code>Power.charging</code> を設定し、<code>toggle()</code> は <code>Power.open</code> を反転する。</li></ul>\n<h3>Pill.qml</h3><ul><li>Rectangle、上部中央、<code>y: 6</code>、黒。サイズ:idle 100 x 26、alert 240 x 48、expanded 300 x 120。<code>Power.mode</code> に対する<b>状態</b>で切り替え、width と height の <code>Behavior</code>(150〜400 ms)でアニメーションする。<code>radius: Math.min(height / 2, 18)</code>。</li><li>Idle:白いテキスト <code>Power.battery + "%"</code>(例:<code>80%</code>)。Alert:テキスト <code>Low battery: 15%</code>。それぞれ自分のモードのときだけ。</li><li>Expanded:<code>Power.devices</code> に対する <code>ListView</code> で、<code>Mouse: 55%</code> のような行。レベルが 20 以下の行は <code>#ff5555</code>、他は白。expanded モードのときだけ。</li><li>上端に沿った <code>MouseArea</code>(高さ 26)が <code>Power.open</code> を切り替える。</li></ul>',
  stories: ['<b>Singleton:</b><code>Power.qml</code> は <code>pragma Singleton</code> で始まりルートは <code>Singleton</code>。初期値は battery 80、charging false、open false、mode <code>"idle"</code>。', '<b>ウィンドウ:</b><code>Variants</code> から画面ごとに 1 つの <code>PanelWindow</code>、上・左・右にアンカー(下はなし)、高さ 140、<code>exclusiveZone: 0</code>、透明。', '<b>レイヤー:</b>すべてのウィンドウが Overlay レイヤーにあり、namespace は <code>"power"</code>。', '<b>マスク:</b>すべてのウィンドウに <code>mask: Region { item: pill }</code> があり、ピルはそのウィンドウ自身の <code>Pill</code> で、アイドル時は 100 x 26、中央、<code>y: 6</code>。', '<b>アイドル:</b>テキスト <code>80%</code> がすべての画面に表示され、警告テキストは見えない。', '<b>IPC:</b><code>power level</code> がバッテリーを設定し(0..100 に制限)、アイドルのテキストが追従する。', '<b>警告:</b>15 % ではモードが <code>"alert"</code> になり、ピルは半径 18 の 240 x 48 で、テキスト <code>Low battery: 15%</code> がアイドルのテキストに置き換わる。', '<b>境界:</b>20 % は警告、21 % は警告ではない。', '<b>充電</b>で警告が解除され、プラグを抜くと戻る。', '<b>展開:</b><code>power toggle</code> が 300 x 120 のピルを開き(alert より優先)、行 <code>Laptop: 80%</code>、<code>Mouse: 55%</code>、<code>Keyboard: 12%</code> を表示する。もう一度切り替えると閉じる。', '<b>色:</b>レベル 20 以下の行(Keyboard)は <code>#ff5555</code>、他は白。', '<b>クリック:</b>ピルをクリックすると展開し、もう一度クリックすると折りたたまれる。', '<b>動き:</b>ピルは <code>State</code> と、width・height の <code>Behavior</code>(150〜400 ms)を使う。'] },
 'm8-r': { title: '復習:アイランドプロジェクト', desc: 'アーキテクチャ、チェックリスト、次にやること。',
  html: '<h2>Dynamic Island を作り上げました</h2>\n<table class="cs"><tr><th>部品</th><th>ルール</th></tr>\n<tr><td><code>Store</code>(Singleton)</td><td>すべての状態とそのルール:モード、データ、モデル、タイマー。変更する唯一の手段は関数。</td></tr>\n<tr><td><code>Island</code>(コンポーネント)</td><td>見た目だけ。<code>states</code> + <code>when</code> がサイズを選び、<code>Behavior</code> がアニメーションし、<code>visible</code> が内容を選ぶ。</td></tr>\n<tr><td><code>main.qml</code></td><td>画面に対する <code>Variants</code>、<code>PanelWindow</code> の設定、Store の関数を呼ぶ <code>IpcHandler</code>。</td></tr>\n<tr><td>ウィンドウ</td><td>ピルより高い。<code>exclusiveZone: 0</code>。透明。ピルに <code>mask</code>。Overlay レイヤー。namespace。</td></tr>\n<tr><td>リスト</td><td>Store に <code>ListModel</code>、アイランドに <code>ListView</code> + デリゲート、<code>model.role</code> と <code>index</code>。</td></tr>\n<tr><td>タイマー</td><td>発火のたびに <code>restart()</code> して、最後のイベントだけが有効になるようにする。</td></tr></table>\n<h3>認定チェックリスト</h3>\n<ul><li>状態を Singleton に置く理由を説明できる。</li><li>State でモードを作り、Behavior でアニメーションさせられる。</li><li>マスクでウィンドウをクリック透過にし、スペースを確保させないようにできる。</li><li>IPC 関数を追加し、ターミナルから呼び出せる。</li><li>ListView でモデルを表示し、インデックスで行を削除できる。</li></ul>\n<p><b>次は:</b>本物のシェルでアイデアを試してみましょう。アイデア:メディアモード(<code>Process</code> でトラック名を取得)、<code>Quickshell.Services.SystemTray</code> のトレイ一覧、niri のイベントを出力する <code>Process</code> を <code>SplitParser</code> で読むワークスペース。サンドボックスではこれらは動きませんが、<code>quickshell.org/docs</code> にある本物の Quickshell のドキュメントが扱っています。</p>' }
});
}
})();
